def migrate_legacy():
    # Preserve source rows and their histories/files; never manufacture a measurement date.
    bind = op.get_bind()
    meta = sa.MetaData()
    tables = {n:sa.Table(n,meta,autoload_with=bind) for n in
        ['tasks','task_types','deadlines','issue_tags','tags','work_tasks','kr_metrics','kr_periods','kr_links','kr_history']}
    tasks=tables['tasks']; metrics=tables['kr_metrics']; periods=tables['kr_periods']
    kinds=tables['task_types']; deadlines=tables['deadlines']
    rows=bind.execute(sa.select(tasks).join(kinds,tasks.c.task_type_id==kinds.c.id).where(
        kinds.c.code=='metric_kr',tasks.c.metric_id.is_(None))).mappings().all()
    for raw in rows:
        t=dict(raw)
        snapshot=json.loads(json.dumps(t,default=str,ensure_ascii=False))
        tags=bind.execute(sa.select(tables['tags'].c.name).join(tables['issue_tags'],
            tables['issue_tags'].c.tag_id==tables['tags'].c.id).where(tables['issue_tags'].c.issue_id==t['id'])).scalars().all()
        mid=bind.execute(metrics.insert().values(title=t['title'],description=t.get('description') or '',
            team_id=t['team_id'],owner_id=t.get('owner_id'),project_id=t.get('project_id'),
            unit=t.get('metric_kr_unit') or '',method='',source='',involved_team_ids=t.get('involved_teams') or [],
            tags=list(tags),priority_id=t.get('priority_id'),business_customer_id=t.get('business_customer_id'),
            department_id=t.get('department_id'),did_client_group_id=t.get('did_client_group_id'),
            legacy_task_id=t['id'],legacy_snapshot=snapshot,is_archived=bool(t.get('is_deleted')),
            version=1,created_by=t.get('created_by'))).inserted_primary_key[0]
        deadline=bind.execute(sa.select(deadlines).where(deadlines.c.id==t.get('deadline_id'))).mappings().first()
        text=' '.join(str(deadline.get(k) or '') for k in ['code','name']) if deadline else ''
        year=re.search(r'20\d{2}',text)
        quarter=re.search(r'(?:Q|КВАРТАЛ\s*)([1-4])',text,re.I) or re.search(r'([1-4])\s*(?:КВ|КВАРТАЛ)',text,re.I)
        if year and quarter:
            y=int(year[0]); q=int(quarter[1]); end_month=q*3
            bind.execute(periods.insert().values(metric_id=mid,label=f'{q} квартал {y}',
                start_date=date(y,end_month-2,1),end_date=date(y,end_month,calendar.monthrange(y,end_month)[1]),
                state='draft',target=t.get('metric_kr_plan'),legacy_fact=t.get('metric_kr_fact'),
                cadence='weekly',weight=t.get('assessment_weight'),forecast=t.get('completion_forecast'),
                method_snapshot='',source_snapshot='',unit_snapshot=t.get('metric_kr_unit') or '',closing_note=''))
        for wid in bind.execute(sa.select(tables['work_tasks'].c.id).where(tables['work_tasks'].c.major_task_id==t['id'])).scalars():
            bind.execute(tables['kr_links'].insert().values(metric_id=mid,work_task_id=wid,created_by=t.get('created_by')))
        bind.execute(tables['kr_history'].insert().values(metric_id=mid,actor_id=t.get('created_by'),
            action='migrated',before={},after={'legacy_task_id':t['id'],'needs_clarification':True},
            reason='Перенос метрического KR; исходный факт сохранён без даты'))
        bind.execute(tasks.update().where(tasks.c.id==t['id']).values(metric_id=mid))

